    if (!env.razorpayWebhookSecret) {
      console.error("[razorpay webhook] RAZORPAY_WEBHOOK_SECRET not set \u2014 rejecting");
      return c.json({ error: "Webhook not configured" }, 500);
    }
    const expected = crypto4.createHmac("sha256", env.razorpayWebhookSecret).update(rawBody).digest("hex");
